{"command": "cd /testbed && cat > /tmp/explore15.py <<'EOF'
from sqlglot.lineage import lineage
S = {"t": {"v": "INT", "cat": "TEXT"}}
sqls = [
  "WITH s AS (SELECT v, cat FROM t) SELECT * FROM s PIVOT(SUM(v) FOR cat IN ('a' AS a)) AS p (x)",
  "WITH s AS (SELECT v, cat FROM t) SELECT * FROM s PIVOT(SUM(v) FOR cat IN ('a' AS a, 'b' AS b)) AS p (x, y)",
  "SELECT * FROM (SELECT v, cat FROM t) AS s PIVOT(SUM(v) FOR cat IN ('a' AS a, 'b' AS b)) AS p (x, y)",
]
for sql in sqls:
    try:
        res = lineage(None, sql, S)
        print("OK", list(res), {k: [x.name for x in v.walk()] for k,v in res.items()})
    except Exception as e:
        print("ERR", type(e).__name__, e)
EOF
for seed in 0 1 2 3 4 5; do echo "seed $seed"; PYTHONHASHSEED=$seed python /tmp/explore15.py; done"}

